'use strict';
const $ = id => document.getElementById(id);
const presets = {
 'news.html': {item:'article.news-item', fields:[['Заголовок','h2',''],['Дата','time','datetime'],['Категорія','.category',''],['Опис','p',''],['Посилання','a','href']]},
 'register.html': {item:'tbody tr',fields:[['Ідентифікатор','td:nth-child(1)',''],['Предмет','td:nth-child(2)',''],['Дата','td:nth-child(3)',''],['Сума, грн','td:nth-child(4)',''],['Статус','td:nth-child(5)','']]},
 'links.html': {item:'.resource',fields:[['Назва','a',''],['URL','a','href'],['Тип','.type',''],['Опис','p','']]},
 custom: {item:'article',fields:[['Заголовок','h2',''],['Текст','p',''],['Посилання','a','href']]}
};
const state={mode:'demo', html:'', rows:[], keys:[], metadata:null, log:[], filterKey:'', rules:null, loaded:false};
function el(tag,txt,cls){const n=document.createElement(tag);if(txt!==undefined)n.textContent=txt;if(cls)n.className=cls;return n;}
function appendLog(msg,kind=''){state.log.push({time:new Date().toISOString(),message:msg,kind});const line=el('div',undefined,'log '+kind);line.append(el('time',state.log.at(-1).time.slice(11,23)+' UTC  '),el('span',msg));if(state.log.length===1)$('logs').replaceChildren();$('logs').append(line);$('logs').scrollTop=$('logs').scrollHeight;}
function status(txt,kind=''){ $('fetchStatus').textContent=txt;$('fetchStatus').className='status '+kind; }
function step(index){document.querySelectorAll('.step').forEach((node,i)=>{node.classList.toggle('active',i===index);node.classList.toggle('done',i<index);});}
function addField(values=['','','']){if($('fields').children.length>=15)return;const row=el('div',undefined,'field'), pair=el('div');const controls=values.map((v,i)=>{const a=document.createElement('input');a.value=v;a.placeholder=['Назва поля','CSS-селектор','textContent'][i];a.setAttribute('aria-label',a.placeholder);a.spellcheck=false;return a;});pair.append(controls[0],controls[1]);const remove=el('button','×');remove.type='button';remove.setAttribute('aria-label','Видалити поле');remove.onclick=()=>row.remove();row.append(pair,controls[2],remove);$('fields').append(row);}
function resetRules(){const p=presets[state.mode==='demo'?$('demo').value:'custom'];$('itemSelector').value=p.item;$('fields').replaceChildren();p.fields.forEach(addField);}
function clearResult(){state.rows=[];state.keys=[];state.rules=null;state.filterKey='';$('records').textContent='—';$('quality').textContent='—';$('category').replaceChildren(new Option('Усі записи',''));$('search').value='';$('rawJSON').textContent='[]';render();}
function clearSource(){state.html='';state.loaded=false;state.metadata=null;clearResult();for(const id of ['bytes','duration','metaSource','metaTime','metaStatus','metaHash'])$(id).textContent='—';$('raw').textContent='HTML ще не отримано.';$('htmlSize').textContent='';$('stateBadge').textContent='Очікування';status('Готово до запиту');step(0);}
function setMode(mode){state.mode=mode;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));for(const m of ['demo','url','file'])$(m+'Mode').hidden=m!==mode;clearSource();resetRules();}
function isPublicHttps(raw){const u=new URL(raw);if(u.protocol!=='https:'||u.username||u.password||!u.hostname.includes('.')||u.hostname.endsWith('.local')||u.hostname.endsWith('.internal')||/^\d+(?:\.\d+){3}$/.test(u.hostname)||u.hostname.includes(':'))throw Error('Вкажіть HTTPS-адресу публічного домену (не локальну або IP-адресу).');return u.href;}
async function readLimited(response){const limit=2_000_000;const head=Number(response.headers.get('content-length'));if(head>limit)throw Error('HTML перевищує 2 МБ.');if(!response.body){const t=await response.text();if(new TextEncoder().encode(t).length>limit)throw Error('HTML перевищує 2 МБ.');return t;}const reader=response.body.getReader(),decoder=new TextDecoder();let total=0,s='';try{while(true){const {done,value}=await reader.read();if(done)break;total+=value.byteLength;if(total>limit){await reader.cancel();throw Error('HTML перевищує 2 МБ.');}s+=decoder.decode(value,{stream:true});}return s+decoder.decode();}finally{reader.releaseLock();}}
async function sha256(s){if(!crypto.subtle)return 'Недоступно';const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(h),n=>n.toString(16).padStart(2,'0')).join('');}
async function load(){const button=$('load');button.disabled=true;$('parse').disabled=true;document.querySelectorAll('.tab, #demo').forEach(x=>x.disabled=true);clearSource();const start=performance.now();let source='',html='',mode='',http='',base=null,contentType='';let timer;try{if(state.mode==='file'){const f=$('file').files[0];if(f){if(f.size>2_000_000)throw Error('HTML перевищує 2 МБ.');html=await f.text();source='Файл: '+f.name;}else{html=$('pasted').value;source='Вставлений HTML';}mode='Локальний HTML';http='Без HTTP';if(!html.trim())throw Error('Додайте файл або вставте HTML.');if(new TextEncoder().encode(html).length>2_000_000)throw Error('HTML перевищує 2 МБ.');appendLog('Читання локального джерела: '+source);}else{const url=state.mode==='demo'?new URL($('demo').value,location.href).href:isPublicHttps($('url').value.trim());source=url;mode=state.mode==='demo'?'Навчальне джерело':'Прямий CORS-запит';status('GET '+url);appendLog('GET '+url);const controller=new AbortController();timer=setTimeout(()=>controller.abort(),12000);const response=await fetch(url,{mode:'cors',credentials:'omit',redirect:'error',signal:controller.signal,cache:'no-store'});http=response.status+' '+response.statusText;appendLog('HTTP '+http,response.ok?'good':'bad');if(!response.ok)throw Error('HTTP '+http);contentType=response.headers.get('content-type')||'';if(contentType&&!/html|xhtml|plain/i.test(contentType))throw Error('Очікується HTML, отримано '+contentType);html=await readLimited(response);base=response.url||url;source=base;}
 const bytes=new TextEncoder().encode(html).length,ms=Math.round(performance.now()-start);if(!html.trim())throw Error('Джерело порожнє.');state.html=html;state.loaded=true;state.metadata={source,mode,http,contentType,base,collectedAt:new Date().toISOString(),htmlBytes:bytes,requestMs:ms,sha256:await sha256(html)};const m=state.metadata;$('raw').textContent=html;$('htmlSize').textContent=bytes.toLocaleString('uk-UA')+' B';$('bytes').textContent=bytes.toLocaleString('uk-UA');$('duration').textContent=ms+' мс';$('metaSource').textContent=source;$('metaTime').textContent=m.collectedAt;$('metaStatus').textContent=http+' / '+mode;$('metaHash').textContent=m.sha256;status('HTML отримано · '+bytes.toLocaleString('uk-UA')+' B','ok');$('stateBadge').textContent='HTML отримано';step(1);appendLog('HTML отримано: '+bytes+' байт; '+ms+' мс','good');appendLog('SHA-256: '+m.sha256);}
 catch(e){const message=e.name==='AbortError'?'Перевищено 12 секунд очікування.':e instanceof TypeError&&state.mode==='url'?'Не вдалося отримати HTML: CORS, мережа або перенаправлення. Використайте дозволене навчальне джерело або імпорт HTML.':e.message;appendLog(message,'bad');status(message,'bad');$('stateBadge').textContent='Помилка';}finally{clearTimeout(timer);button.disabled=false;$('parse').disabled=false;document.querySelectorAll('.tab, #demo').forEach(x=>x.disabled=false);}}
function normalize(v){return (v??'').replace(/\s+/g,' ').trim();}
function safeLink(v,base){try{const u=new URL(v,base||undefined);if(['https:','http:'].includes(u.protocol))return u.href;}catch{}return null;}
function parse(){if(!state.loaded){status('Спершу отримайте HTML.','bad');return;}try{const item=$('itemSelector').value.trim();if(!item)throw Error('CSS-селектор запису порожній.');const fields=Array.from($('fields').children).map(row=>Array.from(row.querySelectorAll('input'),n=>n.value.trim()));if(!fields.length)throw Error('Додайте щонайменше одне поле.');const names=fields.map(f=>f[0]);if(names.some(n=>!n)||new Set(names).size!==names.length)throw Error('Назви полів мають бути непорожніми та унікальними.');const doc=new DOMParser().parseFromString(state.html,'text/html');fields.forEach(f=>{if(f[1])doc.querySelector(f[1]);});const items=Array.from(doc.querySelectorAll(item));const max=500;let nonempty=0;state.rows=items.slice(0,max).map(node=>{const result=Object.create(null);for(const [name,selector,attr] of fields){const target=selector?node.querySelector(selector):node;let value=target?normalize(attr?target.getAttribute(attr):target.textContent):'';if(value&&['href','src'].includes(attr.toLowerCase()))value=safeLink(value,state.metadata.base)||value;result[name]=value;if(value)nonempty++;}return result;});state.keys=names;state.rules={itemSelector:item,fields:fields.map(([name,selector,attribute])=>({name,selector,attribute:attribute||'textContent'})),totalMatches:items.length,limit:max};state.filterKey=names.find(n=>/категор|тип|статус|category|type|status/i.test(n))||names[0];const ratio=state.rows.length?Math.round(100*nonempty/(state.rows.length*fields.length)):0;$('records').textContent=state.rows.length;$('quality').textContent=ratio+'%';$('category').replaceChildren(new Option('Усі записи',''));const values=[...new Set(state.rows.map(r=>r[state.filterKey]).filter(Boolean))].sort();if(values.length<=60)values.forEach(v=>$('category').add(new Option(v,v)));else $('category').add(new Option('Багато значень: скористайтесь пошуком',''));$('search').value='';$('stateBadge').textContent=state.rows.length?'Дані вилучено':'Немає збігів';status('Збігів: '+items.length+'; вилучено: '+state.rows.length+(items.length>max?' (ліміт 500)':''),'ok');appendLog('CSS '+item+' → '+items.length+' збігів; '+fields.length+' полів; '+ratio+'% заповненості','good');step(2);switchView('table');render();}catch(e){clearResult();$('stateBadge').textContent='Помилка правил';status('Помилка правил: '+e.message,'bad');appendLog('Помилка парсингу: '+e.message,'bad');}}
function filtered(){const q=$('search').value.trim().toLowerCase(), v=$('category').value;return state.rows.filter(r=>(!v||r[state.filterKey]===v)&&(!q||state.keys.some(k=>r[k].toLowerCase().includes(q))));}
function render(){const data=filtered();$('count').textContent=data.length+' / '+state.rows.length+' записів';$('rawJSON').textContent=JSON.stringify(data,null,2);for(const id of ['csv','json','report'])$(id).disabled=!data.length;const wrap=$('tablewrap');if(!data.length){const empty=el('div',undefined,'empty');empty.append(el('span','⌕'),el('h3',state.rows.length?'Нічого не знайдено':state.rules?'Селектор не знайшов записів':'Почніть із джерела'),el('p',state.rows.length?'Змініть фільтр або пошук.':state.rules?'Перевірте структуру HTML і CSS-селектор.':'Натисніть «Отримати HTML», потім «Вилучити дані».'));wrap.replaceChildren(empty);return;}const t=el('table'),head=el('thead'),hr=el('tr'),body=el('tbody');['#',...state.keys].forEach(k=>hr.append(el('th',k)));head.append(hr);data.forEach((row,i)=>{const tr=el('tr');tr.append(el('td',String(i+1)));state.keys.forEach(k=>{const td=el('td');const value=row[k];if(/^https?:\/\//i.test(value)&&safeLink(value)){const a=el('a',value);a.href=safeLink(value);a.target='_blank';a.rel='noopener noreferrer';td.append(a);}else td.textContent=value||'—';tr.append(td);});body.append(tr);});t.append(head,body);wrap.replaceChildren(t);}
function switchView(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('current',x.dataset.view===view));for(const v of ['table','html','json','log'])$(v+'View').hidden=v!==view;}
function download(name,content,mime){const u=URL.createObjectURL(new Blob([content],{type:mime}));const a=el('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);appendLog('Експорт: '+name,'good');step(3);}
function csvCell(v){const value=String(v??'');return '"'+(/^[\s]*[=+\-@]/.test(value)?"'"+value:value).replace(/"/g,'""')+'"';}
function report(){const {base,...metadata}=state.metadata;return {project:'OSINT Scraping Lab',note:'Спостереження з HTML; дані потребують незалежної перевірки. Демо-джерела синтетичні.',metadata,rules:state.rules,filters:{query:$('search').value,field:state.filterKey,value:$('category').value},records:filtered()};}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelectorAll('.view').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('demo').onchange=()=>{$('sourceLink').href=$('demo').value;clearSource();resetRules();};$('load').onclick=load;$('parse').onclick=parse;$('resetRules').onclick=resetRules;$('addField').onclick=()=>addField();$('search').oninput=render;$('category').onchange=render;$('csv').onclick=()=>download('osint-data.csv','\ufeff'+[state.keys,...filtered().map(r=>state.keys.map(k=>r[k]))].map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');$('json').onclick=()=>download('osint-data.json',JSON.stringify(filtered(),null,2),'application/json');$('report').onclick=()=>download('osint-report.json',JSON.stringify(report(),null,2),'application/json');$('copyHTML').onclick=async()=>{try{await navigator.clipboard.writeText(state.html);appendLog('HTML скопійовано','good');}catch{appendLog('Копіювання недоступне','bad');}};$('copyJSON').onclick=async()=>{try{await navigator.clipboard.writeText(JSON.stringify(filtered(),null,2));appendLog('JSON скопійовано','good');}catch{appendLog('Копіювання недоступне','bad');}};$('clearLog').onclick=()=>{state.log=[];$('logs').replaceChildren(el('p','Журнал очищено.','muted'));};resetRules();
$('parse').addEventListener('click',()=>{if(state.rules)document.querySelector('.output').scrollIntoView({block:'start',behavior:'smooth'});});
